"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { Button } from "@/components/ui/button";

/** A fan of photographs that opens into a circular arc. Requires motion and Button. */
export function CircularSpread({
  images
}: {
  images: {
    id: string;
    src: string;
    label: string;
  }[];
}) {
  const [open, setOpen] = useState(false);
  const [selected, setSelected] = useState<string | null>(null);
  const reduce = useReducedMotion();
  return <div className="relative h-[310px] w-[300px] max-w-full">
      {images.map((image, i) => {
      const angle = images.length > 1 ? (i / (images.length - 1) - 0.5) * 150 : 0;
      const radians = angle * Math.PI / 180;
      const active = selected === image.id;
      return <Button key={image.id} asChild variant="ghost" className="absolute left-1/2 top-1/2 h-[142px] w-[100px] overflow-hidden rounded-lg border-[3px] border-card bg-card p-0 shadow-lg hover:bg-card" aria-label={`Select ${image.label}`} aria-pressed={active}>
            <motion.button style={{
          marginLeft: -50,
          marginTop: -94,
          zIndex: active ? 20 : i + 1
        }} animate={{
          x: open ? Math.sin(radians) * 88 : (i - (images.length - 1) / 2) * 8,
          y: open ? -Math.cos(radians) * 52 + 24 : 12,
          rotate: active ? 0 : open ? angle * 0.45 : (i - (images.length - 1) / 2) * 8,
          scale: active ? 1.12 : 1
        }} transition={reduce ? {
          duration: 0
        } : {
          type: "spring",
          stiffness: 240,
          damping: 22
        }} onClick={() => {
          if (!open) setOpen(true);else setSelected(active ? null : image.id);
        }}>
              <img src={image.src} alt={image.label} draggable={false} className="h-full w-full object-cover" />
            </motion.button>
          </Button>;
    })}
      <Button variant="secondary" size="sm" className="absolute bottom-1 left-1/2 -translate-x-1/2 rounded-full" aria-expanded={open} onClick={() => {
      setOpen(!open);
      setSelected(null);
    }}>
        {open ? "Gather" : "Spread"}
      </Button>
    </div>;
}

